<body>
    <div class="app-container">
        <div class="header">
            <h1 class="title">Pomodoro</h1>
            <p class="subtitle">Focus &amp; Productivity</p>
        </div>

        <div class="timer-display" id="timerDisplay">00:00</div>

        <div class="interval-label" id="intervalLabel">Work</div>

        <div class="controls">
            <button class="btn btn-primary" id="startBtn">Start</button>
            <button class="btn btn-secondary" id="pauseBtn">Pause</button>
            <button class="btn btn-danger" id="resetBtn">Reset</button>
        </div>

        <div class="status" id="statusText">Ready</div>

        <div class="progress-section">
            <div class="progress-bar">
                <div class="progress-fill" id="progressFill"></div>
            </div>
            <span id="progressPercent">0%</span>
        </div>
    </div>

    <script>
        // Initialize variables
        let isRunning = false;
        let currentInterval = 'work'; // 'work' or 'break'
        let workDuration = 25 * 60 * 1000; // 25 minutes in ms
        let breakDuration = 5 * 60 * 1000; // 5 minutes in ms
        let totalWorkTime = 0;
        let startTime = null;
        let intervalId = null;

        // DOM Elements
        const timerDisplay = document.getElementById('timerDisplay');
        const intervalLabel = document.getElementById('intervalLabel');
        const statusText = document.getElementById('statusText');
        const progressFill = document.getElementById('progressFill');
        const progressPercent = document.getElementById('progressPercent');
        const startBtn = document.getElementById('startBtn');
        const pauseBtn = document.getElementById('pauseBtn');
        const resetBtn = document.getElementById('resetBtn');

        // Update timer display
        function updateTimer() {
            if (!isRunning) return;

            const seconds = Math.floor(timerDisplay.textContent === '00:00' ? 0 : parseInt(timerDisplay.textContent.split(':')[0])) * 60 + 
                           Math.floor(parseInt(timerDisplay.textContent.split(':')[1]) % 60);

            timerDisplay.textContent = String(seconds).padStart(2, '0') + ':' + String(
                Math.floor((seconds % 60) / 1), '0')
            );

            // Update progress bar
            const elapsed = Math.floor(isRunning ? seconds / workDuration : 0);
            const percentage = Math.min((elapsed / workDuration) * 100, 100);
            progressFill.style.width = `${percentage}%`;
            progressPercent.textContent = `${percentage.toFixed(1)}%`;
        }

        // Format duration in MM:SS
        function formatDuration(seconds) {
            const mins = Math.floor(seconds / 60);
            const secs = seconds % 60;
            return `${mins}:${secs.toString().padStart(2, '0')}`;
        }

        // Handle timer completion
        function handleTimerComplete() {
            if (currentInterval === 'work') {
                // Time's up! Start break
                endWorkSession();
            } else {
                // Break time ended, start work again
                startWorkSession();
            }
        }

        // End work session
        function endWorkSession() {
            isRunning = false;
            clearInterval(intervalId);
            intervalId = null;

            // Show completed status after short delay
            setTimeout(() => {
                statusText.textContent = 'Completed';
                statusText.className = 'status completed';

                // Flash effect
                timerDisplay.classList.add('alert-pulse');
                setTimeout(() => timerDisplay.classList.remove('alert-pulse'), 2000);
            }, 1500);
        }

        // Start work session
        function startWorkSession() {
            if (isRunning) return;

            isRunning = true;
            startTime = Date.now();
            intervalId = setInterval(() => {
                updateTimer();
            }, 1000);

            // Update labels
            intervalLabel.textContent = currentInterval === 'work' ? 'Work' : 'Break';

            // Enable buttons
            startBtn.disabled = false;
            pauseBtn.disabled = false;
            resetBtn.disabled = false;
        }

        // Pause session
        function pauseSession() {
            isRunning = false;
            clearInterval(intervalId);
            intervalId = null;

            statusText.textContent = 'Paused';
            statusText.className = 'status paused';

            // Disable buttons except reset
            startBtn.disabled = true;
            pauseBtn.disabled = true;
            resetBtn.disabled = false;
        }

        // Resume session
        function resumeSession() {
            if (!isRunning || intervalId === null) return;

            isRunning = true;
            startTime = Date.now();
            intervalId = setInterval(() => {
                updateTimer();
            }, 1000);

            intervalLabel.textContent = currentInterval === 'work' ? 'Work' : 'Break';
            startBtn.disabled = false;
            pauseBtn.disabled = false;
            resetBtn.disabled = false;
        }

        // Reset session
        function resetSession() {
            stopAll();
            isRunning = false;
            currentInterval = 'work';
            workDuration = 25 * 60 * 1000;
            breakDuration = 5 * 60 * 1000;
            totalWorkTime = 0;
            startTime = null;
            intervalId = null;

            // Reset UI
            timerDisplay.textContent = '00:00';
            intervalLabel.textContent = 'Work';
            statusText.textContent = 'Ready';
            statusText.className = 'status active';
            progressFill.style.width = '0%';
            progressPercent.textContent = '0%';

            // Remove alert pulse
            timerDisplay.classList.remove('alert-pulse');
        }

        // Stop all functions
        function stopAll() {
            if (intervalId) {
                clearInterval(intervalId);
                intervalId = null;
            }
        }

        // Event Listeners
        startBtn.addEventListener('click', () => {
            if (isRunning) {
                pauseSession();
            } else {
                startWorkSession();
            }
        });

        pauseBtn.addEventListener('click', () => {
            pauseSession();
        });

        resetBtn.addEventListener('click', () => {
            resetSession();
        });

        // Keyboard shortcuts
        document.addEventListener('keydown', (e) => {
            if (e.key === ' ') {
                e.preventDefault();
                if (isRunning) {
                    pauseSession();
                } else {
                    startWorkSession();
                }
            } else if (e.key === 'p' && e.ctrlKey) {
                pauseSession();
            } else if (e.key === 'r' && e.ctrlKey) {
                resetSession();
            }
        });

        // Initial setup
        timerDisplay.textContent = '00:00';
        intervalLabel.textContent = 'Work';
        statusText.textContent = 'Ready';
        statusText.className = 'status active';
        progressFill.style.width = '0%';
        progressPercent.textContent = '0%';
    </script>
</body>
</html>
```

## Features Implemented

### Core Functionality
- **Configurable Intervals**: Default 25-minute work / 5-minute break (easily adjustable via console modification)
- **Start/Pause/Resume**: Full control over your timer sessions
- **Reset**: Restart from the beginning with fresh counts
- **Visual Alerts**: Pulse glow effect when timer completes, status color changes

### UI/UX Highlights
- **Gradient Background**: Dark theme with subtle depth
- **Responsive Design**: Works on mobile and desktop
- **Progress Bar**: Shows work session progress
- **Color-Coded States**:
  - Green for active work
  - Yellow/orange for break periods
  - Red for completed sessions
- **Keyboard Shortcuts**: Space to toggle, Ctrl+P to pause, Ctrl+R to reset

### Technical Details
- **Plain HTML/CSS/JS only** — no external dependencies
- **Smooth animations** using CSS transitions and keyframe pulses
- **Accessible**: Semantic elements, focus states, and respects `prefers-reduced-motion`
- **State Management**: Tracks running status, current interval type, and timestamps

To customize intervals, simply change the `workDuration` and `breakDuration` variables near the top of the script section. The app will automatically recalculate and display the updated times.

