<h1>Pomodoro Timer</h1>

<div class="controls">
  <label>
    Work (min)
    <input id="workMin" type="number" min="1" value="25">
  </label>
  <label>
    Break (min)
    <input id="breakMin" type="number" min="1" value="5">
  </label>
  <button id="startBtn">Start</button>
</div>

<div id="timer">00:00</div>
<div id="status">Press “Start” to begin</div>

<button id="pauseBtn" class="btn">Pause</button>
<button id="resetBtn" class="btn">Reset</button>

<div id="alert" class="alert">
  Time’s up!
</div>

<script>
(() => {
  // ----- State variables -----
  let workMinutes = 25;
  let breakMinutes = 5;
  let totalWork, totalBreak;
  let remainingSeconds = 0;
  let isPaused = false;
  let timerId = null;
  let phase = 'work'; // 'work' | 'break'

  const timerEl = document.getElementById('timer');
  const statusEl = document.getElementById('status');
  const alertEl = document.getElementById('alert');
  const workInput = document.getElementById('workMin');
  const breakInput = document.getElementById('breakMin');
  const startBtn = document.getElementById('startBtn');
  const pauseBtn = document.getElementById('pauseBtn');
  const resetBtn = document.getElementById('resetBtn');

  // ----- Helper functions -----
  const fmt = sec => {
    const m = Math.floor(sec / 60).toString().padStart(2, '0');
    const s = Math.floor(sec % 60).toString().padStart(2, '0');
    return `${m}:${s}`;
  };

  const updateDisplay = () => {
    timerEl.textContent = fmt(remainingSeconds);
  };

  const showAlert = () => {
    alertEl.classList.add('show');
    // optional beep
    const beep = new Audio('data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEAIlYAAESsAAACABAAZGF0YQgAA');
    beep.play().catch(() => {});
  };

  const hideAlert = () => alertEl.classList.remove('show');

  const transitionPhase = () => {
    phase = phase === 'work' ? 'break' : 'work';
    statusEl.textContent = phase === 'work' ? 'Work time' : 'Break time';
    remainingSeconds = phase === 'work' ? totalWork : totalBreak;
    updateDisplay();
  };

  const startTimer = () => {
    if (timerId !== null) return; // already running

    // initialise totals if not done yet
    if (!totalWork) {
      totalWork = workMinutes * 60;
      totalBreak = breakMinutes * 60;
    }

    // if we are at the very beginning (no time set), set to work
    if (remainingSeconds === 0) {
      remainingSeconds = totalWork;
    }

    isPaused = false;
    pauseBtn.textContent = 'Pause';
    statusEl.textContent = phase === 'work' ? 'Work time' : 'Break time';
    updateDisplay();

    timerId = setInterval(() => {
      if (!isPaused) {
        remainingSeconds--;
        updateDisplay();

        if (remainingSeconds <= 0) {
          clearInterval(timerId);
          timerId = null;
          playBeepAndFlash();
          transitionPhase();
        }
      }
    }, 1000);
  };

  const pauseTimer = () => {
    if (timerId === null) return;
    isPaused = true;
    pauseBtn.textContent = 'Resume';
  };

  const resumeTimer = () => {
    if (timerId === null) return;
    isPaused = false;
    pauseBtn.textContent = 'Pause';
  };

  const resetTimer = () => {
    clearInterval(timerId);
    timerId = null;
    isPaused = true;
    pauseBtn.textContent = 'Pause';
    statusEl.textContent = 'Press “Start” to begin';
    remainingSeconds = 0;
    updateDisplay();
    hideAlert();
  };

  const playBeepAndFlash = () => {
    // flash red background on the timer for 1 second
    timerEl.style.color = 'var(--danger)';
    timerEl.style.textShadow = '0 0 10px var(--danger)';
    showAlert();
    setTimeout(() => {
      timerEl.style.color = 'var(--primary)';
      timerEl.style.textShadow = 'none';
    }, 1000);
  };

  // ----- Event listeners -----
  startBtn.addEventListener('click', () => {
    // update config if user changed the inputs
    workMinutes = parseInt(workInput.value, 10) || 25;
    breakMinutes = parseInt(breakInput.value, 10) || 5;
    // re‑calculate totals
    totalWork = workMinutes * 60;
    totalBreak = breakMinutes * 60;
    startTimer();
  });

  pauseBtn.addEventListener('click', () => {
    if (timerId === null) return; // not running
    if (isPaused) {
      resumeTimer();
    } else {
      pauseTimer();
    }
  });

  resetBtn.addEventListener('click', resetTimer);

  // Update totals if the user changes the inputs while the timer is running
  workInput.addEventListener('change', () => {
    if (timerId === null) {
      workMinutes = parseInt(workInput.value, 10) || 25;
      totalWork = workMinutes * 60;
    }
  });
  breakInput.addEventListener('change', () => {
    if (timerId === null) {
      breakMinutes = parseInt(breakInput.value, 10) || 5;
      totalBreak = breakMinutes * 60;
    }
  });

  // Initial display
  updateDisplay();
})();
</script>

</body>
</html>
```

### How it works
| Feature | Implementation |
|---------|----------------|
| **Configurable intervals** | Two `<input type="number">` fields (`#workMin`, `#breakMin`). Their values are read when the **Start** button is pressed (or when the timer is reset). |
| **Start** | Initializes `totalWork` / `totalBreak` (seconds) and begins a `setInterval` that ticks every second. |
| **Pause / Resume** | The same button toggles the `isPaused` flag; the interval is cleared on pause and restarted on resume. |
| **Reset** | Clears any running interval, sets the timer back to the initial work‑time, stops the pause state, and hides any alert overlay. |
| **Visual alert** | When the countdown reaches zero, the timer text turns red, a semi‑transparent overlay with “Time’s up!” appears, and a short beep (generated from a data‑URL) plays. |
| **Responsive UI** | Flexbox centers everything; a media query reduces font size and input width on screens narrower than 480 px. |

The whole app lives in a single HTML file, uses **only** plain HTML, CSS and JavaScript, and should work on any modern browser without additional libraries. Enjoy your Pomodoro sessions!

Below is a **complete, self‑contained Pomodoro timer** built with only HTML, CSS and vanilla JavaScript.  
It lets the user:

* Set custom **work** and **break** lengths (in minutes).  
* **Start / Pause** the timer.  
* **Reset** to the configured work interval.  
* See a **visual alert** (screen flash + optional audio beep) when a period ends.  
* Use a **responsive layout** that works on phones, tablets and desktops.

You can copy the three code blocks into a single file (e.g., `index.html`) and open it in any browser.

